"""Independent reference implementation of docs/SPEC.md, written directly from
the SPEC text (deliberately NOT importing anything from workspace/pipeline).

Used to verify the fixed pipeline and to compute report.json numbers.
"""
import json
import sqlite3
from collections import Counter
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

WS = Path(__file__).parent / "workspace"

WEIGHTS = {
    "account_access": 3, "billing": 3, "technical_error": 3, "product_defect": 3,
    "refunds": 2, "shipping": 2, "returns": 2, "data_privacy": 2, "subscription": 2,
    "warranty": 1, "feature_request": 1, "general_inquiry": 1,
}

ALIASES = {
    "login issue": "account_access", "sign in": "account_access",
    "signin": "account_access", "locked out": "account_access",
    "payment": "billing", "billing issue": "billing", "invoice": "billing",
    "overcharge": "billing", "refund": "refunds", "money back": "refunds",
    "bug": "technical_error", "crash": "technical_error", "error": "technical_error",
    "site down": "technical_error", "defect": "product_defect",
    "broken item": "product_defect", "faulty": "product_defect",
    "delivery": "shipping", "package": "shipping", "tracking": "shipping",
    "return": "returns", "exchange": "returns", "privacy": "data_privacy",
    "gdpr request": "data_privacy", "delete my data": "data_privacy",
    "cancel subscription": "subscription", "upgrade plan": "subscription",
    "downgrade": "subscription", "guarantee": "warranty",
    "suggestion": "feature_request", "feature idea": "feature_request",
    "question": "general_inquiry", "other": "general_inquiry",
    "account access": "account_access", "technical error": "technical_error",
    "product defect": "product_defect", "data privacy": "data_privacy",
    "feature request": "feature_request", "general inquiry": "general_inquiry",
}


def normalize(raw):
    # SPEC 2.2 (before collapsing): _ and - -> space; then 2.1: lowercase,
    # strip, collapse unicode whitespace (str.split covers U+00A0 etc.)
    s = raw.replace("_", " ").replace("-", " ")
    s = " ".join(s.lower().split())
    return ALIASES.get(s, s)  # 2.3: at most once, whole-string


def read_jsonl(path):
    with open(path, encoding="utf-8") as f:
        return [json.loads(l) for l in f if l.strip()]


def shard_of(eid):
    return f"shard_{int(eid.split('-')[1]) // 333:02d}"


def round4(x):
    return float(Decimal(str(x)).quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP))


def correct_rows():
    """Correct results-table rows per SPEC: one per (model, gold example)."""
    gold = {r["example_id"]: r["label"] for r in read_jsonl(WS / "data/gold/gold_labels.jsonl")}
    # first occurrence wins in shard-file order (SPEC 3.3)
    firsts = {}  # (model, eid) -> raw label
    models = set()
    for i in range(12):
        for row in read_jsonl(WS / f"data/predictions/shard_{i:02d}.jsonl"):
            models.add(row["model"])
            eid = row["example_id"]
            if eid not in gold:
                continue  # SPEC 3.4
            firsts.setdefault((row["model"], eid), row["label"])
    rows = []
    for model in sorted(models):
        for eid, glabel in gold.items():
            raw = firsts.get((model, eid))
            if raw is None:
                final = None
            else:
                final = normalize(raw)
                if final not in WEIGHTS:
                    final = None
            rows.append((model, eid, shard_of(eid), glabel, raw, final))
    return gold, sorted(models), rows


def scores_from_rows(gold, models, rows):
    gold_present = set(gold.values())
    scores = {}
    for model in models:
        c = {cat: {"tp": 0, "fp": 0, "fn": 0} for cat in WEIGHTS}
        for m, eid, sh, glabel, raw, final in rows:
            if m != model:
                continue
            if final is None:
                c[glabel]["fn"] += 1
            elif final == glabel:
                c[glabel]["tp"] += 1
            else:
                c[final]["fp"] += 1
                c[glabel]["fn"] += 1
        f1 = {}
        for cat, k in c.items():
            d = 2 * k["tp"] + k["fp"] + k["fn"]
            f1[cat] = (2 * k["tp"] / d) if d else 0.0
        num = sum(WEIGHTS[cat] * f1[cat] for cat in WEIGHTS if cat in gold_present)
        den = sum(WEIGHTS[cat] for cat in WEIGHTS if cat in gold_present)
        scores[model] = round4(num / den)
    return scores


def rank(scores):
    return [m for m, _ in sorted(scores.items(), key=lambda kv: (-kv[1], kv[0]))]


def main():
    gold, models, rows = correct_rows()
    scores = scores_from_rows(gold, models, rows)
    ranking = rank(scores)
    print("corrected overall:", json.dumps(scores, indent=2))
    print("corrected ranking:", ranking)

    # --- shard anomaly diff vs August DB backup ---
    aug = sqlite3.connect(Path(__file__).parent / "august_results_backup.sqlite")
    aug_rows = aug.execute(
        "SELECT model, example_id, shard, gold_label, raw_label, final_label FROM results"
    ).fetchall()
    correct_by_shard = {}
    for r in rows:
        correct_by_shard.setdefault(r[2], Counter())[r] += 1
    aug_by_shard = {}
    for r in aug_rows:
        aug_by_shard.setdefault(r[2], Counter())[r] += 1
    anomalies = []
    for i in range(12):
        sh = f"shard_{i:02d}"
        cor = correct_by_shard.get(sh, Counter())
        got = aug_by_shard.get(sh, Counter())
        n_cor, n_got = sum(cor.values()), sum(got.values())
        if cor == got:
            continue
        print(f"{sh}: differs. correct={n_cor} august={n_got} "
              f"only_in_august={sum((got - cor).values())} only_in_correct={sum((cor - got).values())}")
        if n_got > n_cor:
            anomalies.append({"shard": sh, "defect": "surplus_rows", "n_rows": n_got - n_cor})
        elif n_got < n_cor:
            anomalies.append({"shard": sh, "defect": "missing_rows", "n_rows": n_cor - n_got})
        else:
            anomalies.append({"shard": sh, "defect": "content_mismatch_same_count", "n_rows": 0})
    print("anomalies:", json.dumps(anomalies, indent=2))

    # --- compare fixed pipeline DB (if present after rerun) ---
    dbp = WS / "db/results.sqlite"
    cur = sqlite3.connect(dbp)
    new_rows = cur.execute(
        "SELECT model, example_id, shard, gold_label, raw_label, final_label FROM results"
    ).fetchall()
    if Counter(new_rows) == Counter(rows):
        print("PIPELINE DB MATCHES REFERENCE EXACTLY (row multiset equal)")
    else:
        d1 = Counter(new_rows) - Counter(rows)
        d2 = Counter(rows) - Counter(new_rows)
        print(f"PIPELINE DB DIFFERS: extra={sum(d1.values())} missing={sum(d2.values())}")
        for r in list(d1)[:5]: print("  extra:", r)
        for r in list(d2)[:5]: print("  missing:", r)

    with open(Path(__file__).parent / "reference_out.json", "w") as f:
        json.dump({"scores": scores, "ranking": ranking, "anomalies": anomalies}, f, indent=2)


if __name__ == "__main__":
    main()

