"""Configurable scorer used to validate the acceptance suite: make(None)
is a correct SPEC implementation; make(bug) injects one deliberate defect.
"""
import re
from decimal import Decimal, ROUND_HALF_UP

CANON = {
    "account_access": 3, "billing": 3, "technical_error": 3, "product_defect": 3,
    "refunds": 2, "shipping": 2, "returns": 2, "data_privacy": 2, "subscription": 2,
    "warranty": 1, "feature_request": 1, "general_inquiry": 1,
}
ALIASES = {
    "login issue": "account_access", "sign in": "account_access",
    "signin": "account_access", "locked out": "account_access",
    "payment": "billing", "billing issue": "billing", "invoice": "billing",
    "overcharge": "billing", "refund": "refunds", "money back": "refunds",
    "bug": "technical_error", "crash": "technical_error", "error": "technical_error",
    "site down": "technical_error", "defect": "product_defect",
    "broken item": "product_defect", "faulty": "product_defect",
    "delivery": "shipping", "package": "shipping", "tracking": "shipping",
    "return": "returns", "exchange": "returns", "privacy": "data_privacy",
    "gdpr request": "data_privacy", "delete my data": "data_privacy",
    "cancel subscription": "subscription", "upgrade plan": "subscription",
    "downgrade": "subscription", "guarantee": "warranty",
    "suggestion": "feature_request", "feature idea": "feature_request",
    "question": "general_inquiry", "other": "general_inquiry",
    "account access": "account_access", "technical error": "technical_error",
    "product defect": "product_defect", "data privacy": "data_privacy",
    "feature request": "feature_request", "general inquiry": "general_inquiry",
}


def make(bug=None):
    def normalize(raw):
        s = raw
        if bug != "no_separator":
            s = s.replace("_", " ").replace("-", " ")
        if bug != "no_lowercase":
            s = s.lower()
        if bug == "ascii_ws_only":
            s = " ".join(x for x in s.split(" ") if x).strip()
        elif bug != "no_collapse":
            s = " ".join(s.split())
        else:
            s = s.strip()
        if bug == "no_alias":
            return s
        if bug == "alias_substring":
            for k, v in ALIASES.items():
                if k in s:
                    return v
            return s
        return ALIASES.get(s, s)

    def round4(x):
        if bug == "bankers":
            return round(x, 4)
        if bug == "truncate":
            return float(Decimal(str(x)).quantize(Decimal("0.0001"), rounding="ROUND_DOWN"))
        if bug == "no_round":
            return x
        return float(Decimal(str(x)).quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP))

    def score_model(gold, predictions, weights):
        seen = {}
        for row in predictions:
            eid = row["example_id"]
            if eid not in gold and bug != "stray_counted":
                continue
            if eid in seen and bug != "last_wins":
                continue
            seen[eid] = row["label"]
        if bug == "stray_counted":
            stray = {e: l for e, l in seen.items() if e not in gold}
            seen = {e: l for e, l in seen.items() if e in gold}
        counts = {c: {"tp": 0, "fp": 0, "fn": 0} for c in weights}
        for eid, glabel in gold.items():
            if eid not in seen:
                if bug != "missing_ignored":
                    counts[glabel]["fn"] += 1
                continue
            final = normalize(seen[eid])
            valid = final in CANON
            if valid and final == glabel:
                counts[glabel]["tp"] += 1
            elif valid:
                if final in counts:
                    counts[final]["fp"] += 1
                counts[glabel]["fn"] += 1
            else:
                if bug != "invalid_dropped":
                    counts[glabel]["fn"] += 1
        if bug == "stray_counted":
